(()=>{document.querySelectorAll(".markdown pre").forEach(e=>{const i=e.querySelector("code");if(!i||e.closest(".jw-code-block"))return;const s=document.createElement("div");s.className="jw-code-block",e.before(s),s.append(e);const t=document.createElement("button");t.type="button",t.className="jw-code-copy";const r={copy:'<rect x="8" y="8" width="11" height="12"/><path d="M15 8V4H4v12h4"/>',success:'<path d="m4 12 5 5L20 6"/>',error:'<path d="m6 6 12 12M18 6 6 18"/>'},o=(e,n)=>{t.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true">${r[e]}</svg>`,t.setAttribute("aria-label",n),t.title=n};o("copy","复制代码");const n=document.createElement("span");n.className="jw-visually-hidden",n.setAttribute("role","status"),s.append(t,n);let a;t.addEventListener("click",async()=>{clearTimeout(a);try{await navigator.clipboard.writeText(i.textContent),o("success","代码已复制"),n.textContent="代码已复制"}catch{o("error","复制失败，请重试"),n.textContent="复制失败，请选择代码后手动复制"}a=setTimeout(()=>{o("copy","复制代码"),n.textContent=""},2e3)})})})()